    await xem('bam-dup', MANG.length - r.n0 === 1, 'bấm gửi hai lần liền chỉ ra một lượt gọi', 'bấm gửi hai lần liền ra ' + (MANG.length - r.n0) + ' lượt gọi'); await choMang(r.n0);
