    await xem('cau-dai', !!b && bb.right <= kb.right + 1 && bb.left >= kb.left - 1 && khung.scrollWidth <= khung.clientWidth + 1, 'câu rất dài nằm gọn trong khung', b ? 'câu rất dài tràn ra ngoài khung' : 'không tìm thấy bong bóng câu dài để đo'); await choMang(r.n0);
