    if (!khung) { const n = timNutMo(); if (!n) { tt('Không dò được nút mở khung AI. Mở khung bằng tay rồi bấm Chạy lại (hoặc đặt __aiThu.CFG.nutMo).'); return; } n.click(); await ngu(900); khung = timKhung(); }
