    root.getElementById('h').addEventListener('mousedown', ev => { if (ev.target.tagName === 'BUTTON') return; keo = true; sx = ev.clientX; sy = ev.clientY; const r = host.getBoundingClientRect(); ox = r.left; oy = r.top; host.style.bottom = 'auto'; host.style.left = ox + 'px'; host.style.top = oy + 'px'; });
